# Genereert de beelden van stap 2 via codex exec (1 generatie per beeld).
# Bestaande bestanden in raw/ worden overgeslagen, zodat opnieuw draaien geen generaties verspilt.
param([string[]]$Only)

$proj = Split-Path -Parent $PSScriptRoot
$codex = (Get-AppxPackage -Name "OpenAI.Codex").InstallLocation + "\app\resources\codex.exe"
$head = Join-Path $proj "raw\hoofd_neutraal.png"

$style = 'Style: cartoon caricature game sprite, thick black outlines, flat bright colours, simple cel shading, friendly and affectionate. No text unless stated, no logos, no real brands, no watermark.'
$green = 'Background: perfectly flat solid pure chroma green #00FF00 filling the whole canvas, no gradient, no floor, no shadow on the background. IMPORTANT: never use bright green, lime or neon green anywhere in the subject itself; any rainbow must use red, orange, yellow, turquoise, blue, purple and pink stripes (turquoise instead of green). Subject centred with a clear green margin on all sides so nothing is cropped.'
$mike = 'The attached image raw/hoofd_neutraal.png is the approved character design of Mike: keep exactly the same person, same hair, same blue-grey eyes, same face shape, same drawing style, same line weight, same colours, same 3/4 angle and same head size in the frame, and keep the purple/silver glitter sparkles on both temples.'

$jobs = [ordered]@{
  'hoofd_blij' = @{ img = $true; prompt = "$mike Draw HEAD ONLY (head and a short bit of neck, no shoulders, no body, no hands). Expression: ecstatic with joy, eyes squeezed shut into happy curved arcs, huge wide open laughing mouth showing the upper teeth, raised eyebrows, rosy cheeks. $style $green Square 1024x1024." }
  'hoofd_vies' = @{ img = $true; prompt = "$mike Draw HEAD ONLY (head and a short bit of neck, no shoulders, no body) plus ONE hand coming up from below that pinches his nose shut between thumb and index finger. Expression: comically disgusted, eyes squinting, eyebrows scrunched, mouth pulled into a wavy grossed-out grimace, tongue slightly out. Skin tone normal (not green). $style $green Square 1024x1024." }
  'lijf' = @{ img = $true; prompt = "The attached image raw/hoofd_neutraal.png shows only the drawing style and skin tone to match; do NOT draw a head. Draw a HEADLESS small chibi cartoon body of a dad, seen from the front, full body from neck stub down to shoes: the body ends at the top in a short bare neck stub, and there is NO head, no face, no hair at all (a separate oversized head is composited later in the game). He wears a dark navy button-up shirt, dark trousers and sneakers, and on his belly a rainbow-striped baby carrier with a tiny happy baby peeking out. Both arms are stretched straight up, far apart, along the left and right sides of the canvas, holding by its two handles one very wide, shallow, white wicker laundry basket high above, horizontally across the very top of the canvas. Layout of the tall canvas: the basket fills the top fifth and spans almost the full width; the two thin arms run vertically near the left and right edges; the torso and legs are small and sit in the bottom third; the large central area between basket, arms and neck stub is completely EMPTY plain background green (that is where the head goes). $style $green Portrait 1024x1536." }
  'poepluier' = @{ img = $false; prompt = "Draw one single object: a rolled-up used white baby diaper with a small comic brown stain and a cute cartoon stink cloud with wavy stink lines rising from it; the stink cloud is mustard yellow-brown (NOT green), and a couple of tiny flies. Funny and cute, not gross. $style $green Square 1024x1024, object fills about 70 percent of the canvas." }
  'gouden_glitterluier' = @{ img = $false; prompt = "Draw one single object: a clean, fresh, neatly folded baby diaper made of shiny gold, covered in gold glitter, with white and pale yellow star sparkles twinkling around it. Glamorous and fabulous, like a treasure. $style $green Square 1024x1024, object fills about 70 percent of the canvas." }
  'bierblikje' = @{ img = $false; prompt = "Draw one single compact object group that instantly reads as BEER: in front a chunky glass beer mug with a handle, completely filled with opaque golden-yellow beer with little bubbles and a big thick opaque white foam head spilling over the rim; right behind it, slightly overlapping, an upright beer can of a fictional brand. The can body is deep dark bottle green (dark emerald, around #0B5D3B, clearly much darker than the background) with a silver top and a rainbow-striped label band (red, orange, yellow, turquoise, blue, purple, pink) with the single word GLITTERPILS in bold white capital letters. The glass must not be see-through: no background colour visible through the mug or handle opening (fill the handle opening with a solid pale blue-white glass tint). $style $green Square 1024x1024, group fills about 75 percent of the canvas." }
  'salmari' = @{ img = $false; prompt = "Draw one single object: an upright liquor bottle of Finnish salty liquorice liqueur. Glossy jet-black bottle with a short neck and a silver screw cap, a white label with a big black diamond (lozenge) shape and the single word SALMARI in bold black capital letters, a small white skull-free winking star sparkle as highlight, and two tiny black diamond-shaped liquorice candies next to the base. Fictional generic design, no real brand logos. Cool and a little dangerous-looking but cute. $style $green Square 1024x1024, bottle fills about 80 percent of the canvas height." }
  'achtergrond_dag' = @{ img = $false; prompt = "Draw a full-bleed background illustration for a vertical mobile game: a bright cheerful morning on an Amsterdam canal. Tall narrow Dutch canal houses with gabled roofs on both sides, a small arched brick bridge in the distance, trees, parked bicycles on the quay, a few small boats on the calm water, a light blue sky with soft clouds and warm morning sunlight. The lower third is a simple, calm, uncluttered cobblestone quay in the foreground where a character will stand, and the upper two thirds stay fairly light and low-contrast so falling game objects remain readable. Cartoon style with clean dark outlines and flat bright pastel colours, matching a caricature sticker style. No people, no characters, no text, no letters, no signs, no logos, no watermark. This is a normal full-colour scene, NOT a green screen. Portrait, 9:16 aspect ratio (for example 1024x1820 or the closest tall portrait size available)." }
}

New-Item -ItemType Directory -Force (Join-Path $proj "raw") | Out-Null
foreach ($name in $jobs.Keys) {
  if ($Only -and ($Only -notcontains $name)) { continue }
  $out = Join-Path $proj "raw\$name.png"
  if (Test-Path $out) { "SKIP $name (bestaat al)"; continue }
  $job = $jobs[$name]
  $prompt = 'Use the $imagegen tool to generate ONE image. ' + $job.prompt + " Save the resulting PNG at its original generated resolution as raw/$name.png in the current working directory (copy it there if the tool saves it elsewhere; do not resize or edit it). Generate exactly one image: do not retry, do not make variations, do not inspect the result. Reply with only the final file path."
  $cargs = @('exec', '--skip-git-repo-check', '-s', 'workspace-write', '-C', $proj)
  if ($job.img) { $cargs += @('-i', $head) }
  $cargs += @('--', $prompt)
  "" | & $codex @cargs *> (Join-Path $proj "raw\$name.log")
  if (Test-Path $out) { "OK   $name" } else { "FAIL $name (zie raw\$name.log)" }
}
